import numpy as np

# Build the grid programmatically following the pattern
# Grid is 28x28
H, W = 28, 28
grid = np.zeros((H, W), dtype=int)

# Color 1 (blue): anti-diagonal from (0,9) to (9,0), i+j = 9
for i in range(10):
    grid[i, 9-i] = 1

# Color 5 (green): anti-diagonal from (1,27) continuing downward-left, i+j = 28 (0-indexed, 28th sum)
# Starting at row 1, col 27: 1 + 27 = 28
for total in range(28, 36):  # from (1,27) to about (8,20)
    i, j = total, 27
    if i < 28 and j >= 0:
        if grid[i, j] == 0:
            grid[i, j] = 5

# Color 3 (red): anti-diagonal from (9,27) going up-left, i+j = 36
for total in range(36, 54):
    i, j = total - 36, 27  # starts with offset 0
    if i < 28 and j >= 0:
        if grid[i, j] == 0:
            grid[i, j] = 3

# Color 4 (yellow): anti-diagonal from (25,27) going up-left, i+j = 52
for offset in range(3):  # (25,27), (26,26), (27,25)
    i = 25 + offset
    j = 27 - offset
    if i < 28 and j >= 0:
        grid[i, j] = 4

# Print the grid
